93	    /**
94	     * Disposable email domains that are refused: an owner whose email domain is on this blocklist
95	     * is rejected. The value is the already-normalized (trimmed, lower-cased) email's domain.
96	     */
97	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
98	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
99	
100	    /**
101	     * Common address abbreviations expanded to their full form during address normalization.
102	     * Matching is performed per whitespace-separated token on the upper-cased value.
103	     */
104	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
105	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
106	
107	    /**
108	     * Required national-number length (the digits after the country code) per E.164 country code.
109	     * A number whose country code appears here must carry exactly the mapped number of national
110	     * digits; country codes not listed fall back to the generic 8-to-15 total-digit rule.
111	     */
112	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
113	        Map.of("61", 9, "1", 10);
114	
115	    /**
116	     * Inclusive 4-digit postcode range {@code {low, high}} per region, the fixed ground truth for
117	     * validating an owner's postcode against the region derived from its city. A region not listed
118	     * here (e.g. the {@code "UNKNOWN"} locality of an unmapped city) imposes no range constraint, so
119	     * any 4-digit postcode is accepted.
120	     */
121	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
122	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
123	
124	    /**
125	     * City -> canonical region, the fixed ground truth for deriving the region a postcode is
126	     * validated against. A city not listed here derives the {@code "UNKNOWN"} region, which imposes
127	     * no postcode-range constraint.
128	     */
129	    private static final Map<String, String> CITY_REGION = Map.of(
130	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
131	
132	    /**
133	     * The HTTP header carrying a client-supplied idempotency token for owner creation. When a create
134	     * repeats with a token already seen, the originally created owner is returned rather than a
135	     * duplicate being made.
136	     */
137	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
138	
