146	     * Source of the {@code seq} field on the structured {@code OWNER_CREATED} audit event: a
147	     * monotonically increasing integer stamped on each owner create, across all creates.
148	     */
149	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
