194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
197	        HttpHeaders headers = new HttpHeaders();
198	        String idempotencyKey = currentIdempotencyKey();
199	        if (idempotencyKey != null) {
200	            Integer existingId = idempotentCreates.get(idempotencyKey);
201	            if (existingId != null) {
202	                Owner existing = this.clinicService.findOwnerById(existingId);
203	                if (existing != null) {
204	                    // Repeat of a create already performed under this key: return the original
205	                    // owner with 200 instead of creating a duplicate.
206	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
207	                }
208	            }
209	        }
210	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
211	        LocalDate suppliedDate = owner.getRegistrationDate();
212	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
213	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
214	        }
215	        LocalDate effectiveDate = suppliedDate != null ? suppliedDate : LocalDate.now();
216	        LocalDate registrationDate = toBusinessDay(effectiveDate);
217	        owner.setRegistrationDate(registrationDate);
218	        long createdToday = this.clinicService.findAllOwners().stream()
219	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
220	            .count();
221	        if (createdToday >= 100) {
222	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
223	        }
224	        owner.setBulkSignupWarning(createdToday > 80);
225	        if (!applyAddress(owner)) {
226	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
227	        }
228	        String telephone = toE164(owner.getTelephone());
229	        if (telephone == null) {
230	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
231	        }
232	        owner.setTelephone(telephone);
233	        if (owner.getEmail() != null) {
234	            String email = normalizeEmail(owner.getEmail());
235	            if (!EMAIL_PATTERN.matcher(email).matches()) {
236	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
237	            }
238	            if (isDisposableEmailDomain(email)) {
239	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
240	            }
241	            owner.setEmail(email);
242	        }
243	        if (!isPostcodeValidForCity(owner.getPostcode(), regionForCity(owner.getCity()))) {
244	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
245	        }
246	        String cityKey = householdKey(owner.getCity());
247	        long cityCount = this.clinicService.findAllOwners().stream()
248	            .filter(existing -> existing.getCity() != null
249	                && cityKey.equals(householdKey(existing.getCity())))
250	            .count();
251	        if (cityCount >= 50) {
252	            return new ResponseEntity<>(HttpStatus.CONFLICT);
253	        }
254	        // Approaching-capacity warning: the city already holds 40-49 owners, just short of the
255	        // hard limit of 50. The 50+ rejection above still applies unchanged.
256	        owner.setCapacityWarning(cityCount >= 40 && cityCount < 50);
257	        // The household is keyed on (normalized last name, postcode): every owner derives the same
258	        // deterministic householdId from those two fields, so owners sharing them are the same
259	        // household. This computed id is what duplicate detection and the household size below key off.
260	        String householdId = householdId(owner);
261	        owner.setHouseholdId(householdId);
262	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
263	            .filter(existing -> !existing.getDeleted())
264	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
265	            .toList();
266	        owner.setHouseholdSize(householdMembers.size() + 1);
267	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
268	        // Duplicate detection is now the single identityKey (below): the separate household-duplicate
269	        // 409 block from the computed householdId no longer applies. Two owners sharing a last name and
270	        // postcode but with different telephones therefore have different identity keys and are admitted
271	        // as a soft match rather than rejected. The householdId and householdSize computed above still
272	        // drive household sizing and the level ceiling below.
273	        // Level ceiling: an owner admitted into an already-populated household without declaring
274	        // membership has its membership level capped at one above the household's current maximum, so
275	        // an undeclared newcomer can never outrank the household it joined. Declared members and
276	        // household founders are left uncapped. With no existing household member no cap applies.
277	        if (!householdMembers.isEmpty() && !sharesHousehold) {
278	            int maxHouseholdLevel = householdMembers.stream()
279	                .mapToInt(Owner::getMembershipLevel)
280	                .max()
281	                .orElse(0);
282	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
283	        }
284	        // Single consolidated duplicate check: the telephone, email and household duplicate rules are
285	        // all expressed through the one derived identityKey (telephone|email|householdId). A create is
286	        // rejected only when a new owner's WHOLE identityKey equals an existing owner's; because the
287	        // telephone is part of the key, two household members with different telephones are allowed.
288	        // This still catches a full identity repeat even when it declares sharesHousehold.
289	        String identityKey = owner.getIdentityKey();
290	        boolean identityInUse = this.clinicService.findAllOwners().stream()
291	            .filter(existing -> !existing.getDeleted())
292	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
293	        if (identityInUse) {
294	            return new ResponseEntity<>(HttpStatus.CONFLICT);
295	        }
296	        // Soft-duplicate detection. A declared household member (sharesHousehold) is never a suspected
297	        // duplicate. Any other owner whose identityKey differs from an existing owner's but that shares
298	        // that owner's Soundex(last name) and postcode is flagged as a possible duplicate of the
299	        // earliest such owner. A full identity match would already have been rejected as a 409 above,
300	        // so every existing owner reaching here necessarily has a different identityKey.
301	        if (sharesHousehold) {
302	            owner.setPossibleDuplicate(false);
303	        } else {
304	            String softDuplicateLastNameSoundex = Owner.soundex(owner.getLastName());
305	            String softDuplicatePostcode = owner.getPostcode();
306	            Owner possibleDuplicate = softDuplicatePostcode == null ? null
307	                : this.clinicService.findAllOwners().stream()
308	                    .filter(existing -> !existing.getDeleted())
309	                    .filter(existing -> softDuplicateLastNameSoundex.equals(Owner.soundex(existing.getLastName())))
310	                    .filter(existing -> softDuplicatePostcode.equals(existing.getPostcode()))
311	                    .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
312	                    .min(Comparator.comparing(Owner::getId))
313	                    .orElse(null);
314	            if (possibleDuplicate != null) {
315	                owner.setPossibleDuplicate(true);
316	                owner.setPossibleDuplicateOf(possibleDuplicate.getId());
317	            } else {
318	                owner.setPossibleDuplicate(false);
319	            }
320	        }
321	        owner.setMemberId(memberId(owner));
322	        String firstNameKey = householdKey(owner.getFirstName());
323	        String namesakeLastNameKey = householdKey(owner.getLastName());
324	        long namesakeCount = this.clinicService.findAllOwners().stream()
325	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
326	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
327	            .count();
328	        owner.setNamesakeCount((int) namesakeCount);
329	        this.clinicService.saveOwner(owner);
330	        if (idempotencyKey != null) {
331	            idempotentCreates.put(idempotencyKey, owner.getId());
332	        }
333	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
334	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
335	            owner.getMembershipLevel());
336	        OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_CREATED_SEQUENCE.incrementAndGet(),
337	            owner.getId(), primaryIdentifier(owner), owner.getMembershipLevel());
338	        AUDIT.info("{}", event.toJson());
339	        // Enqueue a welcome notification for the freshly created owner, carrying the owner id and
340	        // the member id so downstream delivery can address and personalize it.
341	        NOTIFY.info("welcome ownerId={} memberId={}", owner.getId(), owner.getMemberId());
342	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
343	        headers.setLocation(UriComponentsBuilder.newInstance()
344	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
345	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
346	    }
347	
348	    /**
349	     * Validates an owner's postcode against the region derived from its city. The postcode is
350	     * optional: a {@code null} value is always accepted. When present it must fall within the
351	     * inclusive range mapped to the region by {@link #REGION_POSTCODES}; a region with no known
352	     * range (e.g. the {@code "UNKNOWN"} locality of an unmapped city) accepts any 4-digit postcode.
353	     * The 4-digit syntax itself is enforced upstream by bean validation.
354	     *
355	     * @param postcode the owner's postcode (may be {@code null})
356	     * @param locality the region derived from the owner's city
357	     * @return {@code true} when the postcode is absent, the region has no range, or the postcode is
358	     *         within the region's range; {@code false} when it is out of range
359	     */
360	    /**
361	     * The canonical region for the given city via the fixed {@link #CITY_REGION} table, or
362	     * {@code "UNKNOWN"} when the city is {@code null} or not in the table.
363	     *
364	     * @param city the owner's city (may be {@code null})
365	     * @return the canonical region, or {@code "UNKNOWN"}
366	     */
367	    /**
368	     * The {@code Idempotency-Key} header of the current request, trimmed, or {@code null} when the
369	     * header is absent, blank, or no servlet request is bound to the current thread.
370	     *
371	     * @return the idempotency key, or {@code null}
372	     */
373	    private String currentIdempotencyKey() {
374	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
375	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
376	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
377	            if (key != null && !key.isBlank()) {
378	                return key.trim();
379	            }
380	        }
381	        return null;
382	    }
383	
384	    private String regionForCity(String city) {
385	        if (city == null) {
386	            return "UNKNOWN";
387	        }
388	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
389	    }
390	
391	    private boolean isPostcodeValidForCity(String postcode, String locality) {
392	        if (postcode == null) {
393	            return true;
394	        }
395	        int[] range = REGION_POSTCODES.get(locality);
396	        if (range == null) {
397	            return true;
398	        }
399	        int value = Integer.parseInt(postcode);
400	        return value >= range[0] && value <= range[1];
401	    }
402	
403	    /**
404	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
405	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
406	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
407	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
408	     * recognised country codes the national number (the digits after the country code) must also be
409	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
410	     * needs 10); a wrong national-number length yields {@code null}.
411	     *
412	     * @param telephone the raw telephone value (may be {@code null})
413	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
414	     *         a valid E.164 number
415	     */
416	    private String toE164(String telephone) {
417	        if (telephone == null) {
418	            return null;
419	        }
420	        String trimmed = telephone.trim();
421	        boolean hasCountryCode = trimmed.startsWith("+");
422	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
423	        if (hasCountryCode) {
424	            cleaned = cleaned.substring(1);
425	        }
426	        if (!cleaned.matches("[0-9]+")) {
427	            return null;
428	        }
429	        String digits;
430	        if (hasCountryCode) {
431	            digits = cleaned;
432	        } else {
433	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
434	            digits = "61" + national;
435	        }
436	        if (digits.length() < 8 || digits.length() > 15) {
437	            return null;
438	        }
439	        if (!hasValidNationalNumberLength(digits)) {
440	            return null;
441	        }
442	        return "+" + digits;
443	    }
444	
445	    /**
446	     * Checks the national-number length of an E.164 digit string (country code plus national
447	     * number, without the leading {@code '+'}) against its country code. When the number's country
448	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
449	     * country code must number exactly what that country requires; the longest matching country
450	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
451	     * only by the generic total-length rule).
452	     *
453	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
454	     * @return {@code true} if the national-number length is acceptable for the country code
455	     */
456	    private boolean hasValidNationalNumberLength(String digits) {
457	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
458	            .filter(entry -> digits.startsWith(entry.getKey()))
459	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
460	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
461	            .orElse(true);
462	    }
463	
464	    /**
465	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
466	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
467	     *
468	     * @param email the raw email value (must not be {@code null})
469	     * @return the trimmed, lower-cased email
470	     */
471	    private String normalizeEmail(String email) {
472	        return email.trim().toLowerCase(Locale.ROOT);
473	    }
474	
475	    /**
476	     * Whether the domain of the given normalized email is on the disposable-domain blocklist
477	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The domain is the substring after the last {@code '@'};
478	     * an email without an {@code '@'} carries no blocked domain.
479	     *
480	     * @param email the trimmed, lower-cased email
481	     * @return {@code true} when the email's domain is blocklisted
482	     */
483	    private boolean isDisposableEmailDomain(String email) {
484	        int at = email.lastIndexOf('@');
485	        if (at < 0) {
486	            return false;
487	        }
488	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
489	    }
490	
491	    /**
492	     * Applies the owner's address, preferring the structured form over the flat one. When a
493	     * non-blank {@code addressLine1} is supplied the structured fields are normalized in place and
494	     * the flat {@code address} is composed as the normalized {@code addressLine1} followed, when a
495	     * non-blank {@code addressLine2} is present, by a single space and the normalized
496	     * {@code addressLine2}. Otherwise the flat {@code address} is normalized in place. An owner
497	     * that supplies neither a non-blank {@code addressLine1} nor a non-blank flat {@code address}
498	     * is invalid.
499	     *
500	     * @param owner the owner whose address fields are normalized and composed in place
501	     * @return {@code true} when a usable address was applied, {@code false} when none was supplied
502	     */
503	    private boolean applyAddress(Owner owner) {
504	        String line1 = owner.getAddressLine1();
505	        if (line1 != null && !line1.isBlank()) {
506	            String normalizedLine1 = normalizeAddress(line1);
507	            owner.setAddressLine1(normalizedLine1);
508	            String composed = normalizedLine1;
509	            String line2 = owner.getAddressLine2();
510	            if (line2 != null && !line2.isBlank()) {
511	                String normalizedLine2 = normalizeAddress(line2);
512	                owner.setAddressLine2(normalizedLine2);
513	                composed = normalizedLine1 + " " + normalizedLine2;
514	            }
515	            owner.setAddress(composed);
516	            return true;
517	        }
518	        String address = normalizeAddress(owner.getAddress());
519	        if (address == null || address.isEmpty()) {
520	            return false;
521	        }
522	        owner.setAddress(address);
523	        return true;
524	    }
525	
526	    /**
527	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
528	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
529	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
530	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
531	     * normalized form, and every household comparison uses it.
532	     *
533	     * @param address the raw address value (may be {@code null})
534	     * @return the normalized address, or {@code null} if the input was {@code null}
535	     */
536	    private String normalizeAddress(String address) {
537	        if (address == null) {
538	            return null;
539	        }
540	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
541	        if (collapsed.isEmpty()) {
542	            return collapsed;
543	        }
544	        String[] tokens = collapsed.split(" ");
545	        StringBuilder sb = new StringBuilder(collapsed.length());
546	        for (int i = 0; i < tokens.length; i++) {
547	            if (i > 0) {
548	                sb.append(' ');
549	            }
550	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
551	        }
552	        return sb.toString();
553	    }
554	
555	    /**
556	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
557	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
558	     * so that owners are compared case-insensitively with collapsed whitespace.
559	     *
560	     * @param value the raw value (must not be {@code null})
561	     * @return the normalized comparison key
562	     */
563	    private String householdKey(String value) {
564	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
565	    }
566	
567	    /**
568	     * Derives a stable, shared household identifier for the owner's household: the first 12 hex
569	     * characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}, where the
570	     * last name is normalized with {@link #householdKey} and an absent postcode is rendered as the
571	     * empty string. Because it is a pure function of the last name and postcode, every owner sharing
572	     * those two fields derives the identical identifier and therefore belongs to the same household.
573	     *
574	     * @param owner the owner whose household identifier is derived
575	     * @return the stable household identifier
576	     */
577	    private String householdId(Owner owner) {
578	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
579	        String key = householdKey(owner.getLastName()) + "|" + postcode;
580	        try {
581	            byte[] digest = MessageDigest.getInstance("SHA-256")
582	                .digest(key.getBytes(StandardCharsets.UTF_8));
583	            StringBuilder sb = new StringBuilder(digest.length * 2);
584	            for (byte b : digest) {
585	                sb.append(String.format("%02x", b));
586	            }
587	            return sb.substring(0, 12);
588	        }
589	        catch (java.security.NoSuchAlgorithmException e) {
590	            throw new IllegalStateException("SHA-256 not available", e);
591	        }
592	    }
593	
594	    /**
595	     * The owner's current primary identifier, the value carried by the structured
596	     * {@code OWNER_CREATED} audit event: the owner's {@link Owner#getMemberId() memberId}, the
597	     * single unified identifier that replaced the former customer code.
598	     *
599	     * @param owner the freshly created owner (with its member id already assigned)
600	     * @return the owner's current primary identifier
601	     */
602	    private String primaryIdentifier(Owner owner) {
603	        return owner.getMemberId();
604	    }
605	
606	    /**
607	     * Immutable structured audit event emitted alongside the human-readable audit line when an owner
608	     * is created. It is serialized to a compact JSON object and published to the {@code AUDIT}
609	     * logger so it can be routed and asserted independently of the diagnostic log. The
610	     * {@code memberId} field carries the owner's {@link #primaryIdentifier(Owner) current primary
611	     * identifier}, the unified member id.
612	     */
613	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
614	                                     Integer membershipLevel) {
615	
616	        private static final String EVENT = "OWNER_CREATED";
617	
618	        private String toJson() {
619	            return "{\"seq\":" + this.seq
620	                + ",\"ownerId\":" + this.ownerId
621	                + ",\"memberId\":" + quote(this.memberId)
622	                + ",\"membershipLevel\":" + this.membershipLevel
623	                + ",\"event\":\"" + EVENT + "\"}";
624	        }
625	
626	        private static String quote(String value) {
627	            if (value == null) {
628	                return "null";
629	            }
630	            String escaped = value.replace("\\", "\\\\").replace("\"", "\\\"");
631	            return "\"" + escaped + "\"";
632	        }
633	    }
634	
635	    /**
636	     * Builds the member id for a newly registered owner in the form
637	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the region code (the same region
638	     * derivation shared with {@link Owner#getLocality() locality}: postcode range first, falling
639	     * back to the city, or {@code 'UNKNOWN'}); {@code FY} is the 2-digit fiscal year of the
640	     * registration date (the last two digits of {@link Owner#getFiscalYear()}); {@code HASH8} is the
641	     * first 8 upper-case hex characters of the SHA-256 digest of the normalized telephone
642	     * concatenated with the last name (the same HASH8 used by the region-and-hash identity); and
643	     * {@code CHK} is a single Luhn check digit computed over the decimal digits of
644	     * {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW261A2B3C4D7'}). When the computed id collides with
645	     * an existing owner's member id, {@code '-<n>'} is appended using the smallest {@code n} of 2 or
646	     * more that makes the result unique, guaranteeing distinct owners always receive distinct member
647	     * ids.
648	     *
649	     * @param owner the owner whose member id is derived (with normalized telephone and registration
650	     *              date already set)
651	     * @return the assigned member id
652	     */
653	    private String memberId(Owner owner) {
654	        String region = owner.getLocality();
655	        String fiscalYear = owner.getFiscalYear();
656	        String fy = fiscalYear == null ? "00" : fiscalYear.substring(fiscalYear.length() - 2);
657	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName(), 8);
658	        String core = region + fy + hash8;
659	        String base = core + luhnCheckDigit(core);
660	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
661	            .map(Owner::getMemberId)
662	            .filter(id -> id != null)
663	            .collect(Collectors.toSet());
664	        if (!existingIds.contains(base)) {
665	            return base;
666	        }
667	        int n = 2;
668	        while (existingIds.contains(base + "-" + n)) {
669	            n++;
670	        }
671	        return base + "-" + n;
672	    }
673	
674	    /**
675	     * The single Luhn check digit ({@code 0}-{@code 9}) computed with the standard Luhn algorithm
676	     * over the decimal digits contained in {@code value} (non-digit characters are ignored).
677	     *
678	     * @param value the string whose decimal digits are checked
679	     * @return the Luhn check digit
680	     */
681	    private static int luhnCheckDigit(String value) {
682	        int sum = 0;
683	        boolean dbl = true;
684	        for (int i = value.length() - 1; i >= 0; i--) {
685	            char c = value.charAt(i);
686	            if (c < '0' || c > '9') {
687	                continue;
688	            }
689	            int d = c - '0';
690	            if (dbl) {
691	                d *= 2;
692	                if (d > 9) {
693	                    d -= 9;
694	                }
695	            }
696	            sum += d;
697	            dbl = !dbl;
698	        }
699	        return (10 - (sum % 10)) % 10;
700	    }
701	
702	    /**
703	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
704	     * UTF-8 bytes of {@code input}.
705	     *
706	     * @param input  the value to hash
707	     * @param length the number of leading hex characters to keep
708	     * @return the truncated, upper-cased hex digest
709	     */
710	    private String sha256UpperHex(String input, int length) {
711	        try {
712	            byte[] digest = MessageDigest.getInstance("SHA-256")
713	                .digest(input.getBytes(StandardCharsets.UTF_8));
714	            StringBuilder sb = new StringBuilder(digest.length * 2);
715	            for (byte b : digest) {
716	                sb.append(String.format("%02x", b));
717	            }
718	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
719	        }
720	        catch (java.security.NoSuchAlgorithmException e) {
721	            throw new IllegalStateException("SHA-256 not available", e);
722	        }
723	    }
724	
725	    /** Fixed public holidays that the business-day roll skips. */
726	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
727	        LocalDate.parse("2026-01-01"),
728	        LocalDate.parse("2026-01-26"),
729	        LocalDate.parse("2026-04-25"),
730	        LocalDate.parse("2026-12-25"),
731	        LocalDate.parse("2026-12-28"));
732	
733	    /**
734	     * Rolls a registration date forward onto a business day. When the given date falls on a
735	     * Saturday, Sunday or a listed public holiday it is advanced one day at a time until it
736	     * lands on a non-holiday weekday; a business day is returned unchanged.
737	     *
738	     * @param date the effective registration date (must not be {@code null})
739	     * @return the same date if it is already a business day, otherwise the next business day
740	     */
741	    private LocalDate toBusinessDay(LocalDate date) {
742	        while (isNonBusinessDay(date)) {
743	            date = date.plusDays(1);
744	        }
745	        return date;
746	    }
747	
748	    private boolean isNonBusinessDay(LocalDate date) {
749	        DayOfWeek dayOfWeek = date.getDayOfWeek();
750	        return dayOfWeek == DayOfWeek.SATURDAY
751	            || dayOfWeek == DayOfWeek.SUNDAY
752	            || PUBLIC_HOLIDAYS.contains(date);
753	    }
754	
755	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
756	    @Override
757	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
758	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
759	        if (currentOwner == null) {
760	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
761	        }
762	        String email = ownerFieldsDto.getEmail();
763	        if (email != null) {
764	            email = normalizeEmail(email);
765	            if (!EMAIL_PATTERN.matcher(email).matches()) {
766	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
767	            }
768	        }
769	        String telephone = toE164(ownerFieldsDto.getTelephone());
770	        if (telephone == null) {
771	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
772	        }
773	        currentOwner.setAddress(ownerFieldsDto.getAddress());
774	        currentOwner.setCity(ownerFieldsDto.getCity());
775	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
776	        currentOwner.setLastName(ownerFieldsDto.getLastName());
777	        currentOwner.setTelephone(telephone);
778	        currentOwner.setEmail(email);
779	        this.clinicService.saveOwner(currentOwner);
780	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
781	    }
782	
783	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
784	    @Transactional
785	    @Override
786	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
787	        Owner owner = this.clinicService.findOwnerById(ownerId);
788	        if (owner == null) {
789	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
790	        }
791	        // Soft-delete: flag the owner deleted and retain the record so it can still be read back.
792	        owner.setDeleted(true);
793	        this.clinicService.saveOwner(owner);
794	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
795	    }
796	
797	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
798	    @Override
799	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
800	        Owner owner = this.clinicService.findOwnerById(ownerId);
801	        if (owner == null) {
802	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
803	        }
804	        HttpHeaders headers = new HttpHeaders();
805	        Pet pet = petMapper.toPet(petFieldsDto);
806	        owner.setId(ownerId);
807	        pet.setOwner(owner);
808	        pet.getType().setName(null);
809	        this.clinicService.savePet(pet);
810	        PetDto petDto = petMapper.toPetDto(pet);
811	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
812	            .buildAndExpand(pet.getId()).toUri());
813	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
814	    }
815	
816	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
817	    @Override
818	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
819	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
820	        if (currentOwner != null) {
821	            Pet currentPet = this.clinicService.findPetById(petId);
822	            if (currentPet != null) {
823	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
824	                currentPet.setName(petFieldsDto.getName());
825	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
826	                this.clinicService.savePet(currentPet);
827	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
828	            }
829	        }
830	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
831	    }
832	
833	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
834	    @Override
835	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
836	        HttpHeaders headers = new HttpHeaders();
837	        Visit visit = visitMapper.toVisit(visitFieldsDto);
838	        Pet pet = new Pet();
839	        pet.setId(petId);
840	        visit.setPet(pet);
841	        this.clinicService.saveVisit(visit);
842	        VisitDto visitDto = visitMapper.toVisitDto(visit);
843	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
844	            .buildAndExpand(visit.getId()).toUri());
845	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
846	    }
847	
848	
849	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
850	    @Override
851	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
852	        Owner owner = this.clinicService.findOwnerById(ownerId);
853	        if (owner != null) {
854	            Pet pet = owner.getPet(petId);
855	            if (pet != null) {
856	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
857	            }
858	        }
859	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
860	    }
861	}
