118	     * (e.g. {@code "DR Franklin"}), or just the last name when no title has been supplied.
119	     *
120	     * @return the formatted salutation
121	     */
122	    public String getSalutation() {
123	        if (this.title == null || this.title.isBlank()) {
124	            return this.getLastName();
