161	    public String getTelephone() {
162	        return this.telephone;
163	    }
164	
165	    public void setTelephone(String telephone) {
166	        this.telephone = telephone;
167	    }
168	
169	    /**
170	     * The stored E.164 {@link #telephone} formatted for humans as the country code, a single
171	     * space, then the national digits (the digits after the country code) grouped in threes from
172	     * the left, e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}. The country code is
173	     * a single digit for the {@code +1} and {@code +7} zones and two digits otherwise.
174	     *
175	     * @return the human-formatted telephone, or the raw {@link #telephone} unchanged when it is
176	     *         {@code null} or not a {@code +} followed by digits
177	     */
178	    public String getTelephoneDisplay() {
179	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
180	            return this.telephone;
181	        }
182	        String digits = this.telephone.substring(1);
183	        int countryCodeLength = ONE_DIGIT_CALLING_CODES.contains(digits.substring(0, 1)) ? 1 : 2;
184	        if (digits.length() <= countryCodeLength) {
185	            return this.telephone;
186	        }
187	        String countryCode = digits.substring(0, countryCodeLength);
188	        String national = digits.substring(countryCodeLength);
189	        StringBuilder grouped = new StringBuilder();
190	        for (int i = 0; i < national.length(); i++) {
191	            if (i > 0 && i % 3 == 0) {
192	                grouped.append(' ');
193	            }
194	            grouped.append(national.charAt(i));
195	        }
196	        return "+" + countryCode + " " + grouped;
197	    }
198	
199	    /**
200	     * The E.164 calling codes that are a single digit ({@code +1} for the North American Numbering
201	     * Plan and {@code +7} for the Russia/Kazakhstan zone); every other calling code is two digits.
202	     */
203	    private static final Set<String> ONE_DIGIT_CALLING_CODES = Set.of("1", "7");
204	
205	    public String getEmail() {
206	        return this.email;
207	    }
208	
209	    public void setEmail(String email) {
210	        this.email = email;
211	    }
212	
213	    public String getPostcode() {
214	        return this.postcode;
215	    }
216	
217	    public void setPostcode(String postcode) {
218	        this.postcode = postcode;
219	    }
220	
221	    public LocalDate getRegistrationDate() {
222	        return this.registrationDate;
223	    }
224	
225	    public void setRegistrationDate(LocalDate registrationDate) {
226	        this.registrationDate = registrationDate;
227	    }
228	
229	    public LocalDate getBirthDate() {
230	        return this.birthDate;
231	    }
232	
233	    public void setBirthDate(LocalDate birthDate) {
234	        this.birthDate = birthDate;
235	    }
236	
237	    /**
238	     * The owner's age band, derived from the {@link #birthDate} measured in completed years
239	     * against the {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
240	     * from 18 to 64, and {@code "SENIOR"} at 65 and over.
241	     *
242	     * @return the age band, or {@code null} when either the birth date or the registration
243	     *         date has not been assigned
244	     */
245	    public String getAgeBand() {
246	        if (this.birthDate == null || this.registrationDate == null) {
247	            return null;
248	        }
249	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
250	        if (age < 18) {
251	            return "MINOR";
252	        }
253	        if (age < 65) {
254	            return "ADULT";
255	        }
256	        return "SENIOR";
257	    }
258	
259	    /**
260	     * The owner's canonical API path, formed as {@code "/api/owners/"} followed by the owner's
261	     * {@link #getId() id}.
262	     *
263	     * @return the self link, or {@code null} when the owner has not yet been assigned an id
264	     */
265	    public String getSelfLink() {
266	        if (this.getId() == null) {
267	            return null;
268	        }
269	        return "/api/owners/" + this.getId();
270	    }
271	
272	    /**
273	     * The owner's member id, the single unified identifier formatted
274	     * {@code '<REGION><FY><HASH8><CHK>'}: the region code, the 2-digit fiscal year, the 8-character
275	     * upper-hex HASH8 of the region-and-hash identity, and a single Luhn check digit computed over
276	     * the digits of {@code <REGION><FY><HASH8>}. It is assigned on creation (with collision handling)
277	     * and unifies the former customer code, membership number and check digit.
278	     *
279	     * @return the member id, or {@code null} if it has not been assigned
280	     */
281	    public String getMemberId() {
282	        return this.memberId;
283	    }
284	
285	    public void setMemberId(String memberId) {
286	        this.memberId = memberId;
287	    }
288	
289	    public String getHouseholdId() {
290	        return this.householdId;
291	    }
292	
293	    public void setHouseholdId(String householdId) {
294	        this.householdId = householdId;
295	    }
296	
297	    public Integer getNamesakeCount() {
298	        return this.namesakeCount;
299	    }
300	
301	    public void setNamesakeCount(Integer namesakeCount) {
302	        this.namesakeCount = namesakeCount;
303	    }
304	
305	    /**
306	     * Whether more than 80 owners had already been created today at the time this owner
307	     * was created, indicating an unusually high signup volume.
308	     *
309	     * @return {@code true} when the bulk-signup threshold was exceeded, otherwise
310	     *         {@code false} (never {@code null})
311	     */
312	    public Boolean getBulkSignupWarning() {
313	        return this.bulkSignupWarning != null && this.bulkSignupWarning;
314	    }
315	
316	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
317	        this.bulkSignupWarning = bulkSignupWarning;
318	    }
319	
320	    /**
321	     * Whether the owner's city was approaching its capacity limit when this owner
322	     * was created: the city already held between 40 and 49 owners (inclusive), just
323	     * short of the hard limit of 50.
324	     *
325	     * @return {@code true} when the city was approaching capacity, otherwise
326	     *         {@code false} (never {@code null})
327	     */
328	    public Boolean getCapacityWarning() {
329	        return this.capacityWarning != null && this.capacityWarning;
330	    }
331	
332	    public void setCapacityWarning(Boolean capacityWarning) {
333	        this.capacityWarning = capacityWarning;
334	    }
335	
336	    /**
337	     * The number of owners in this owner's household (owners sharing the same
338	     * {@code householdId}) as of when this owner was created, used to derive the GOLD
339	     * membership tier.
340	     *
341	     * @return the household member count, or {@code null} if it has not been assigned
342	     */
343	    public Integer getHouseholdSize() {
344	        return this.householdSize;
345	    }
346	
347	    public void setHouseholdSize(Integer householdSize) {
348	        this.householdSize = householdSize;
349	    }
350	
351	    /**
352	     * The upper bound applied to this owner's {@link #getMembershipLevel() membership level}: one
353	     * above the highest membership level held by their household members at the time this owner was
354	     * created. It is assigned only to an owner admitted into an already-populated household, and is
355	     * {@code null} (no cap) for a household founder or a declared household member, so their level is
356	     * not restricted.
357	     *
358	     * @return the membership-level cap, or {@code null} when no cap applies
359	     */
360	    public Integer getMembershipLevelCap() {
361	        return this.membershipLevelCap;
362	    }
363	
364	    public void setMembershipLevelCap(Integer membershipLevelCap) {
365	        this.membershipLevelCap = membershipLevelCap;
366	    }
367	
368	    /**
369	     * Whether this owner, though not a hard duplicate, shares an existing owner's last name and
370	     * postcode while carrying a different telephone, flagging a likely duplicate registration.
371	     *
372	     * @return {@code true} when a soft-duplicate match was found on creation, otherwise
373	     *         {@code false} (never {@code null})
374	     */
375	    public Boolean getPossibleDuplicate() {
376	        return this.possibleDuplicate != null && this.possibleDuplicate;
377	    }
378	
379	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
380	        this.possibleDuplicate = possibleDuplicate;
381	    }
382	
383	    /**
384	     * The id of the existing owner this owner may duplicate (same last name and postcode,
385	     * different telephone), or {@code null} when this owner is not a possible duplicate.
386	     *
387	     * @return the matching owner id, or {@code null}
388	     */
389	    public Integer getPossibleDuplicateOf() {
390	        return this.possibleDuplicateOf;
391	    }
392	
393	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
394	        this.possibleDuplicateOf = possibleDuplicateOf;
395	    }
396	
397	    /**
398	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; deleting an
399	     * owner via {@code DELETE /api/owners/{id}} flags it {@code true} while retaining the record.
400	     * A deleted owner is ignored by the create endpoint's duplicate and identity checks.
401	     *
402	     * @return {@code true} when the owner has been soft-deleted, otherwise {@code false} (never
403	     *         {@code null})
404	     */
405	    public Boolean getDeleted() {
406	        return this.deleted != null && this.deleted;
407	    }
408	
409	    public void setDeleted(Boolean deleted) {
410	        this.deleted = deleted;
411	    }
412	
413	    /**
414	     * The owner's name formatted as {@code "LastName, FirstName"} from the stored names.
415	     *
416	     * @return the formatted display name
417	     */
418	    public String getDisplayName() {
419	        return this.getLastName() + ", " + this.getFirstName();
420	    }
421	
422	    /**
423	     * The owner's initials: the upper-cased first letters of the first and last
424	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
425	     *
426	     * @return the formatted initials
427	     */
428	    public String getInitials() {
429	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
430	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
431	    }
432	
433	    /**
434	     * The fiscal year of the (business-day-adjusted) {@link #registrationDate}, formatted as
435	     * {@code "FY<YY>"}. The fiscal year starts on 1 July: a registration date on or after 1 July
436	     * belongs to that calendar year's fiscal year, an earlier date belongs to the previous year's,
437	     * and {@code YY} is the last two digits of the year the fiscal year started (e.g. a date in
438	     * August 2026 yields {@code "FY26"}, a date in March 2026 yields {@code "FY25"}).
439	     *
440	     * @return the formatted fiscal year, or {@code null} if the registration date has not been
441	     *         assigned
442	     */
443	    public String getFiscalYear() {
444	        if (this.registrationDate == null) {
445	            return null;
446	        }
447	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
448	    }
449	
450	    /**
451	     * The starting calendar year of the fiscal year (which begins on 1 July) that the given date
452	     * falls in: the date's own year when it is on or after 1 July, otherwise the previous year.
453	     *
454	     * @param date the date whose fiscal year is derived (must not be {@code null})
455	     * @return the starting calendar year of the fiscal year
456	     */
457	    private static int fiscalYearOf(LocalDate date) {
458	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
459	            ? date.getYear() : date.getYear() - 1;
460	    }
461	
462	    /**
463	     * The owner's membership points, starting at {@code 0}. The owner gains {@code 2} when
464	     * they carry an email address, {@code 1} when they have no namesakes
465	     * ({@code namesakeCount} is {@code 0}), {@code 2} for a household of {@code 3} or more
466	     * members ({@code householdSize}), and {@code 3} for tenure of at least one elapsed
467	     * fiscal year (the {@code registrationDate}'s fiscal year precedes the current fiscal
468	     * year, the fiscal year starting on 1 July). Because a newly created owner is still in
469	     * the current fiscal year, a new owner can score at most {@code 5} points.
470	     *
471	     * @return the membership points
472	     */
473	    public Integer getMembershipPoints() {
474	        int points = 0;
475	        boolean hasEmail = this.email != null && !this.email.isBlank();
476	        if (hasEmail) {
477	            points += 2;
478	        }
479	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
480	        if (noNamesakes) {
481	            points += 1;
482	        }
483	        if (this.householdSize != null && this.householdSize >= 3) {
484	            points += 2;
485	        }
486	        if (this.registrationDate != null
487	            && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1) {
488	            points += 3;
489	        }
490	        return points;
491	    }
492	
493	    /**
494	     * The owner's numeric membership level, from {@code 1} to {@code 4}, derived from the
495	     * {@link #getMembershipPoints() membership points}: {@code 1} for {@code 0-1} points,
496	     * {@code 2} for {@code 2-3} points, {@code 3} for {@code 4-5} points, and {@code 4} for
497	     * {@code 6} or more points. Because a newly created owner has zero tenure, a new owner
498	     * scores at most {@code 5} points and so never exceeds level {@code 3}; level {@code 4}
499	     * is reserved for owners whose tenure spans at least one elapsed fiscal year.
500	     *
501	     * <p>When a {@link #getMembershipLevelCap() membership-level cap} has been assigned the
502	     * points-derived level is capped to it, so an owner admitted into an existing household can never
503	     * exceed one level above their household's highest member.
504	     *
505	     * @return the membership level
506	     */
507	    public Integer getMembershipLevel() {
508	        int level = pointsMembershipLevel();
509	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
510	            return this.membershipLevelCap;
511	        }
512	        return level;
513	    }
514	
515	    /**
516	     * The membership level derived purely from the {@link #getMembershipPoints() membership points},
517	     * before any {@link #getMembershipLevelCap() household cap} is applied.
518	     *
519	     * @return the uncapped, points-derived membership level
520	     */
521	    private int pointsMembershipLevel() {
522	        int points = getMembershipPoints();
523	        if (points >= 6) {
524	            return 4;
525	        }
526	        if (points >= 4) {
527	            return 3;
528	        }
529	        if (points >= 2) {
530	            return 2;
531	        }
532	        return 1;
533	    }
534	
535	    /**
536	     * The owner's preferred contact channel: {@code "EMAIL"} when the owner carries an
537	     * email address, otherwise {@code "PHONE"}.
538	     *
539	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
540	     */
541	    public String getContactPreference() {
542	        boolean hasEmail = this.email != null && !this.email.isBlank();
543	        return hasEmail ? "EMAIL" : "PHONE";
544	    }
545	
546	    /**
547	     * The owner's segment, formatted {@code "<TIER>_<AREA>"}, one of {@code "PREMIUM_METRO"},
548	     * {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or {@code "STANDARD_REGIONAL"}. The tier
549	     * is {@code "PREMIUM"} when the {@link #getMembershipLevel() membership level} is {@code 3} or
550	     * more, otherwise {@code "STANDARD"}. The area is {@code "METRO"} when the
551	     * {@link #getLocality() locality} is a known region ({@code NSW}, {@code VIC} or {@code QLD}),
552	     * otherwise {@code "REGIONAL"}.
553	     *
554	     * @return the formatted owner segment
555	     */
556	    public String getOwnerSegment() {
557	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
558	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
559	        return tier + "_" + area;
560	    }
561	
562	    /**
563	     * The owner's identity key: the single derived value used for duplicate detection. It is the
564	     * lower-case, 64-character hex SHA-256 digest over
565	     * {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}, where the telephone
566	     * is the already-normalized stored value, the email is lower-cased (a {@code null} email is
567	     * rendered as the empty string) and the last name is reduced to its Soundex code. Two owners are
568	     * duplicates only when their whole identity keys are equal; because the telephone is part of the
569	     * key, two owners sharing a last name (Soundex) but with different telephones have different
570	     * identity keys and so are not hard duplicates.
571	     *
572	     * @return the derived identity key
573	     */
574	    public String getIdentityKey() {
575	        String telephonePart = this.telephone == null ? "" : this.telephone;
576	        String emailPart = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
577	        String soundexPart = soundex(getLastName());
578	        return sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart);
579	    }
580	
581	    /**
582	     * Returns the lower-case, 64-character hex SHA-256 digest of the UTF-8 bytes of {@code input}.
583	     *
584	     * @param input the value to hash
585	     * @return the full hex digest
586	     */
587	    private static String sha256Hex(String input) {
588	        try {
589	            byte[] digest = MessageDigest.getInstance("SHA-256")
590	                .digest(input.getBytes(StandardCharsets.UTF_8));
591	            StringBuilder sb = new StringBuilder(digest.length * 2);
592	            for (byte b : digest) {
593	                sb.append(String.format("%02x", b));
594	            }
595	            return sb.toString();
596	        }
597	        catch (NoSuchAlgorithmException e) {
598	            throw new IllegalStateException("SHA-256 not available", e);
599	        }
600	    }
601	
602	    /**
603	     * Computes the American Soundex code of a name: the first letter followed by three digits that
604	     * phonetically encode the remaining consonants. Non-letters are ignored, {@code h} and {@code w}
605	     * are transparent (letters either side of them are treated as adjacent) and vowels reset the
606	     * run so a repeated code across a vowel is encoded twice. A {@code null} or letter-free value
607	     * yields the empty string.
608	     *
609	     * @param value the name to encode
610	     * @return the Soundex code, or the empty string when there is no letter to encode
611	     */
612	    public static String soundex(String value) {
613	        if (value == null) {
614	            return "";
615	        }
616	        StringBuilder letters = new StringBuilder();
617	        for (int i = 0; i < value.length(); i++) {
618	            char c = Character.toUpperCase(value.charAt(i));
619	            if (c >= 'A' && c <= 'Z') {
620	                letters.append(c);
621	            }
622	        }
623	        if (letters.length() == 0) {
624	            return "";
625	        }
626	        StringBuilder code = new StringBuilder();
627	        char first = letters.charAt(0);
628	        code.append(first);
629	        char last = soundexDigit(first);
630	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
631	            char c = letters.charAt(i);
632	            if (c == 'H' || c == 'W') {
633	                // Transparent: leave the previous code in place so letters either side stay adjacent.
634	                continue;
635	            }
636	            char digit = soundexDigit(c);
637	            if (digit != '0') {
638	                if (digit != last) {
639	                    code.append(digit);
640	                }
641	                last = digit;
642	            }
643	            else {
644	                // A vowel breaks the run so a following letter with the same code is encoded again.
645	                last = '0';
646	            }
647	        }
648	        while (code.length() < 4) {
649	            code.append('0');
650	        }
651	        return code.toString();
652	    }
653	
654	    /**
655	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for vowels and the
656	     * uncoded letters {@code h} and {@code w}.
657	     */
658	    private static char soundexDigit(char c) {
659	        switch (c) {
660	            case 'B': case 'F': case 'P': case 'V':
661	                return '1';
662	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
663	                return '2';
664	            case 'D': case 'T':
665	                return '3';
666	            case 'L':
667	                return '4';
668	            case 'M': case 'N':
669	                return '5';
670	            case 'R':
671	                return '6';
672	            default:
673	                return '0';
674	        }
675	    }
676	
677	    /**
678	     * City -> canonical region, the fixed ground truth for deriving locality.
679	     */
680	    private static final Map<String, String> CITY_REGION = Map.of(
681	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
682	
683	    /**
684	     * Region -> inclusive 4-digit postcode range {@code {low, high}}, the fixed ground truth for
685	     * deriving locality from the postcode ahead of the city.
686	     */
687	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
688	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
689	
690	    /**
691	     * The owner's locality: the canonical region resolved by the postcode range first
692	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back to the
693	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
694	     * {@code Brisbane->QLD}) when the postcode is absent or in no known range, or {@code "UNKNOWN"}
695	     * when the city is not in the table either. The postcode takes precedence so cities that share a
696	     * name are disambiguated by their postcode's region.
697	     *
698	     * @return the canonical region string, or {@code "UNKNOWN"}
699	     */
700	    public String getLocality() {
701	        String byPostcode = regionForPostcode(this.postcode);
702	        if (byPostcode != null) {
703	            return byPostcode;
704	        }
705	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
706	    }
707	
708	    /**
709	     * Region -> IANA timezone name, the fixed ground truth for deriving the owner's timezone from
710	     * its locality.
711	     */
712	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
713	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
714	
715	    /**
716	     * The owner's timezone: the IANA name resolved from the {@link #getLocality() locality} via the
717	     * fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
718	     * {@code QLD->Australia/Brisbane}), or {@code null} when the locality is not one of these regions
719	     * (e.g. {@code "UNKNOWN"}).
720	     *
721	     * @return the IANA timezone name, or {@code null}
722	     */
723	    public String getTimezone() {
724	        return REGION_TIMEZONE.get(getLocality());
725	    }
726	
727	    /**
728	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
729	     * absent, not a 4-digit number, or in no known range.
730	     *
731	     * @param postcode the owner's postcode (may be {@code null})
732	     * @return the matching region, or {@code null}
733	     */
734	    private static String regionForPostcode(String postcode) {
735	        if (postcode == null || !postcode.matches("\\d{4}")) {
736	            return null;
737	        }
738	        int value = Integer.parseInt(postcode);
739	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
740	            int[] range = entry.getValue();
741	            if (value >= range[0] && value <= range[1]) {
742	                return entry.getKey();
743	            }
744	        }
745	        return null;
746	    }
747	
748	    protected Set<Pet> getPetsInternal() {
749	        if (this.pets == null) {
750	            this.pets = new HashSet<>();
751	        }
752	        return this.pets;
753	    }
754	
755	    protected void setPetsInternal(Set<Pet> pets) {
756	        this.pets = pets;
757	    }
758	
759	    public List<Pet> getPets() {
760	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
761	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
762	        return Collections.unmodifiableList(sortedPets);
763	    }
764	
765	    public void setPets(List<Pet> pets) {
766	        this.pets = new HashSet<>(pets);
767	    }
768	
769	    public void addPet(Pet pet) {
770	        getPetsInternal().add(pet);
771	        pet.setOwner(this);
772	    }
773	
774	    /**
775	     * Return the Pet with the given name, or null if none found for this Owner.
776	     *
777	     * @param name to test
778	     * @return true if pet name is already in use
779	     */
780	    public Pet getPet(String name) {
781	        return getPet(name, false);
782	    }
783	
784	    /**
785	     * Return the Pet with the given name, or null if none found for this Owner.
786	     *
787	     * @param name to test
788	     * @return true if pet name is already in use
789	     */
790	    public Pet getPet(String name, boolean ignoreNew) {
791	        name = name.toLowerCase();
792	        for (Pet pet : getPetsInternal()) {
793	            if (!ignoreNew || !pet.isNew()) {
794	                String compName = pet.getName();
795	                compName = compName.toLowerCase();
796	                if (compName.equals(name)) {
797	                    return pet;
798	                }
799	            }
800	        }
801	        return null;
802	    }
803	
804	    public Pet getPet(Integer petId) {
805	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
806	    }
807	
808	    @Override
809	    public String toString() {
810	        return new ToStringCreator(this)
811	
812	            .append("id", this.getId())
813	            .append("new", this.isNew())
814	            .append("lastName", this.getLastName())
815	            .append("firstName", this.getFirstName())
816	            .append("address", this.address)
817	            .append("city", this.city)
818	            .append("telephone", this.telephone)
819	            .append("email", this.email)
820	            .toString();
821	    }
822	}
